// M467 — the pure-Dart zstd decoder (lib/inventor/zstd.dart).
//
// Vectors made by the reference implementation (python-zstandard 0.22+) over
// levels 1, 3, 19 and a fast level, with and without content size, always
// with a checksum: raw, RLE and compressed blocks, one- and four-stream
// Huffman literals, FSE-described, predefined, RLE and repeated sequence
// tables, multi-block frames. Each decompressed result is checked by length
// and a 64-bit FNV-1a hash of the original.
import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:prototype/inventor/zstd.dart';

int _fnv(Uint8List b) {
  var h = 0xcbf29ce484222325;
  for (final c in b) {
    h = (h ^ c) * 0x100000001b3;
  }
  return h;
}

const _vectors = <(String, int, int, String)>[
  ('empty_l3', 0, 0xcbf29ce484222325, 'KLUv/SQAAQAAmenYUQ=='),
  ('tiny_l3', 3, 0xe71fa2190541574b, 'KLUv/SQDGQAAYWJjmQl3rQ=='),
  ('random2k_l1', 2048, 0x4e74bca899b308d1, ''),
  ('zeros100k_l3', 100000, 0x61b94018df3e37a5, 'KLUv/aSghgEAVQAAEAAAAQCbhjnAAtsjTvM='),
  ('text20k_l1', 20000, 0xcda936c55ac9154e, ''),
  ('text20k_l19', 20000, 0xcda936c55ac9154e, ''),
  ('text20k_l-5', 20000, 0xcda936c55ac9154e, ''),
  ('text200k_l3', 200000, 0x2e2bd0aaeff3acc9, ''),
  ('text200k_l19', 200000, 0x2e2bd0aaeff3acc9, ''),
];

void main() {
  for (final (name, len, hash, b64) in _vectors) {
    test('zstd $name', () {
      final out = zstdDecompress(Uint8List.fromList(base64Decode(b64)));
      expect(out.length, len);
      expect(_fnv(out), hash);
    });
  }

  test('not a zstd stream is refused, not misread', () {
    expect(() => zstdDecompress(Uint8List.fromList([1, 2, 3, 4, 5, 6])),
        throwsA(isA<ZstdException>()));
  });
}
